tasks.solution:
-- 표준 SQL: SELECT branch, SUM(boxes) AS total FROM deliveries GROUP BY ROLLUP(branch);
SELECT branch, SUM(boxes) AS total FROM deliveries GROUP BY branch
-- 이 주석 아래에 전체 합계 행을 이어 붙이는 두 줄을 쓰세요.
UNION ALL
SELECT NULL, SUM(boxes) FROM deliveries
ORDER BY branch NULLS LAST;

